#include <bits/stdc++.h>
using namespace std;

// Decodes the JSON string literal starting at raw[p] == '"' into Unicode code points
// (UTF-8 bytes and \u escapes, joining surrogate pairs); leaves p after the closing quote.
int hex4(const string &raw, size_t p) {
    return stoi(raw.substr(p, 4), nullptr, 16);
}

vector<int> parseJsonString(const string &raw, size_t &p) {
    vector<int> out;
    p++;
    while (raw[p] != '"') {
        unsigned char c = raw[p];
        if (c == '\\') {
            char e = raw[p + 1];
            p += 2;
            if (e == 'u') {
                int u = hex4(raw, p);
                p += 4;
                if (u >= 0xD800 && u < 0xDC00 && raw.compare(p, 2, "\\u") == 0) {
                    int lo = hex4(raw, p + 2);
                    if (lo >= 0xDC00 && lo < 0xE000) {
                        u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00);
                        p += 6;
                    }
                }
                out.push_back(u);
            } else {
                const string from = "\"\\/bfnrt", to = "\"\\/\b\f\n\r\t";
                out.push_back(to[from.find(e)]);
            }
        } else if (c < 0x80) {
            out.push_back(c);
            p++;
        } else {
            int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
            int cp = c & (0x7F >> len);
            for (int i = 1; i < len; i++) cp = (cp << 6) | (raw[p + i] & 0x3F);
            out.push_back(cp);
            p += len;
        }
    }
    p++;
    return out;
}

// Same escaping as Python json.dumps(..., ensure_ascii=True).
string toAsciiJson(const vector<int> &s) {
    string out = "\"";
    char buf[8];
    auto unit = [&](int u) { snprintf(buf, sizeof buf, "\\u%04x", u); out += buf; };
    for (int c : s) {
        if (c == '"') out += "\\\"";
        else if (c == '\\') out += "\\\\";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else if (c == '\b') out += "\\b";
        else if (c == '\f') out += "\\f";
        else if (c >= 0x20 && c < 0x7F) out += (char)c;
        else if (c < 0x10000) unit(c);
        else { int v = c - 0x10000; unit(0xD800 | (v >> 10)); unit(0xDC00 | (v & 0x3FF)); }
    }
    return out + "\"";
}

int main() {
    string raw((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    size_t p = raw.find('"');
    vector<int> s = parseJsonString(raw, p);
    const int CODE_POINTS = 0x110000;
    vector<int> remaining(CODE_POINTS, 0);
    for (int c : s) remaining[c]++;
    // Pair deletions keep each count's parity: exactly the odd-count characters survive, once each.
    vector<char> need(CODE_POINTS, 0), used(CODE_POINTS, 0);
    for (int c : s) need[c] = remaining[c] % 2;
    // Smallest subsequence containing each needed character once (monotonic stack).
    vector<int> st;
    for (int c : s) {
        remaining[c]--;
        if (!need[c] || used[c]) continue;
        while (!st.empty() && st.back() > c && remaining[st.back()] > 0) { used[st.back()] = 0; st.pop_back(); }
        st.push_back(c);
        used[c] = 1;
    }
    cout << toAsciiJson(st) << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] raw;
    static int pos;

    static int hex4(int p) {
        return Integer.parseInt(new String(raw, p, 4), 16);
    }

    // Decodes the JSON string literal starting at raw[pos] == '"' into Unicode code points
    // (UTF-8 bytes and backslash-u escapes, joining surrogate pairs); leaves pos after the closing quote.
    static int[] parseJsonString() {
        int[] out = new int[16];
        int size = 0;
        pos++;
        while (raw[pos] != '"') {
            int c = raw[pos] & 0xFF, cp;
            if (c == '\\') {
                char e = (char) raw[pos + 1];
                pos += 2;
                if (e == 'u') {
                    cp = hex4(pos);
                    pos += 4;
                    if (cp >= 0xD800 && cp < 0xDC00 && raw[pos] == '\\' && raw[pos + 1] == 'u') {
                        int lo = hex4(pos + 2);
                        if (lo >= 0xDC00 && lo < 0xE000) {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            pos += 6;
                        }
                    }
                } else {
                    cp = "\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e));
                }
            } else if (c < 0x80) {
                cp = c;
                pos++;
            } else {
                int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
                cp = c & (0x7F >> len);
                for (int i = 1; i < len; i++) cp = (cp << 6) | (raw[pos + i] & 0x3F);
                pos += len;
            }
            if (size == out.length) out = Arrays.copyOf(out, size * 2);
            out[size++] = cp;
        }
        pos++;
        return Arrays.copyOf(out, size);
    }

    static final char[] HEX = "0123456789abcdef".toCharArray();

    static void unit(StringBuilder out, int u) {
        out.append("\\u");
        for (int shift = 12; shift >= 0; shift -= 4) out.append(HEX[(u >> shift) & 15]);
    }

    // Same escaping as Python json.dumps(..., ensure_ascii=True).
    static String toAsciiJson(int[] s, int size) {
        StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < size; i++) {
            int c = s[i];
            if (c == '"') out.append("\\\"");
            else if (c == '\\') out.append("\\\\");
            else if (c == '\n') out.append("\\n");
            else if (c == '\r') out.append("\\r");
            else if (c == '\t') out.append("\\t");
            else if (c == '\b') out.append("\\b");
            else if (c == '\f') out.append("\\f");
            else if (c >= 0x20 && c < 0x7F) out.append((char) c);
            else if (c < 0x10000) unit(out, c);
            else {
                int v = c - 0x10000;
                unit(out, 0xD800 | (v >> 10));
                unit(out, 0xDC00 | (v & 0x3FF));
            }
        }
        return out.append('"').toString();
    }

    public static void main(String[] args) throws IOException {
        raw = System.in.readAllBytes();
        while (raw[pos] != '"') pos++;
        int[] s = parseJsonString();
        final int CODE_POINTS = 0x110000;
        int[] remaining = new int[CODE_POINTS];
        for (int c : s) remaining[c]++;
        // Pair deletions keep each count's parity: exactly the odd-count characters survive, once each.
        boolean[] need = new boolean[CODE_POINTS], used = new boolean[CODE_POINTS];
        for (int c : s) need[c] = remaining[c] % 2 == 1;
        // Smallest subsequence containing each needed character once (monotonic stack).
        int[] st = new int[s.length];
        int top = 0;
        for (int c : s) {
            remaining[c]--;
            if (!need[c] || used[c]) continue;
            while (top > 0 && st[top - 1] > c && remaining[st[top - 1]] > 0) used[st[--top]] = false;
            st[top++] = c;
            used[c] = true;
        }
        System.out.println(toAsciiJson(st, top));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var raw []byte
var pos int

func hex4(p int) int {
	v, _ := strconv.ParseInt(string(raw[p:p+4]), 16, 32)
	return int(v)
}

// Decodes the JSON string literal starting at raw[pos] == '"' into Unicode code points
// (UTF-8 bytes and \u escapes, joining surrogate pairs); leaves pos after the closing quote.
func parseJSONString() []int {
	var out []int
	pos++
	for raw[pos] != '"' {
		c := int(raw[pos])
		var cp int
		if c == '\\' {
			e := raw[pos+1]
			pos += 2
			if e == 'u' {
				cp = hex4(pos)
				pos += 4
				if cp >= 0xD800 && cp < 0xDC00 && raw[pos] == '\\' && raw[pos+1] == 'u' {
					if lo := hex4(pos + 2); lo >= 0xDC00 && lo < 0xE000 {
						cp = 0x10000 + (cp-0xD800)<<10 + (lo - 0xDC00)
						pos += 6
					}
				}
			} else {
				cp = int("\"\\/\b\f\n\r\t"[strings.IndexByte("\"\\/bfnrt", e)])
			}
		} else if c < 0x80 {
			cp = c
			pos++
		} else {
			n := 2
			if c >= 0xF0 {
				n = 4
			} else if c >= 0xE0 {
				n = 3
			}
			cp = c & (0x7F >> n)
			for i := 1; i < n; i++ {
				cp = cp<<6 | int(raw[pos+i]&0x3F)
			}
			pos += n
		}
		out = append(out, cp)
	}
	pos++
	return out
}

// Same escaping as Python json.dumps(..., ensure_ascii=True).
func toASCIIJSON(s []int) string {
	var out strings.Builder
	out.WriteByte('"')
	unit := func(u int) { fmt.Fprintf(&out, "\\u%04x", u) }
	for _, c := range s {
		switch {
		case c == '"':
			out.WriteString(`\"`)
		case c == '\\':
			out.WriteString(`\\`)
		case c == '\n':
			out.WriteString(`\n`)
		case c == '\r':
			out.WriteString(`\r`)
		case c == '\t':
			out.WriteString(`\t`)
		case c == '\b':
			out.WriteString(`\b`)
		case c == '\f':
			out.WriteString(`\f`)
		case c >= 0x20 && c < 0x7F:
			out.WriteByte(byte(c))
		case c < 0x10000:
			unit(c)
		default:
			v := c - 0x10000
			unit(0xD800 | v>>10)
			unit(0xDC00 | v&0x3FF)
		}
	}
	out.WriteByte('"')
	return out.String()
}

func main() {
	raw, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	for raw[pos] != '"' {
		pos++
	}
	s := parseJSONString()
	const codePoints = 0x110000
	remaining := make([]int32, codePoints)
	for _, c := range s {
		remaining[c]++
	}
	// Pair deletions keep each count's parity: exactly the odd-count characters survive, once each.
	need, used := make([]bool, codePoints), make([]bool, codePoints)
	for _, c := range s {
		need[c] = remaining[c]%2 == 1
	}
	// Smallest subsequence containing each needed character once (monotonic stack).
	var st []int
	for _, c := range s {
		remaining[c]--
		if !need[c] || used[c] {
			continue
		}
		for len(st) > 0 && st[len(st)-1] > c && remaining[st[len(st)-1]] > 0 {
			used[st[len(st)-1]] = false
			st = st[:len(st)-1]
		}
		st = append(st, c)
		used[c] = true
	}
	fmt.Println(toASCIIJSON(st))
}
